import type { ElementType, ReactNode } from "react";
import "./live-experience-hero.css";

export interface LiveExperienceHeroProps {
  title: string;
  description: string;
  actionLabel: string;
  actionHref: string;
  /** Decorative media only. Interactive controls belong outside this block. */
  media?: ReactNode;
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
}

export function LiveExperienceHero({
  title,
  description,
  actionLabel,
  actionHref,
  media,
  headingLevel = 1,
}: LiveExperienceHeroProps) {
  const Heading = `h${headingLevel}` as ElementType;

  return (
    <section className="tb-live-hero">
      <div className="tb-live-hero__media" aria-hidden="true" inert>
        {media ?? (
          <div className="tb-live-hero__placeholder" />
        )}
      </div>
      <div className="tb-live-hero__scrim" aria-hidden="true" />
      <div className="tb-live-hero__copy">
        <Heading className="tb-live-hero__title">{title}</Heading>
        <p>{description}</p>
        <a href={actionHref}>{actionLabel}</a>
      </div>
    </section>
  );
}

.tb-live-hero {
  --tb-leh-accent: #f0c94f;
  position: relative;
  isolation: isolate;
  container-type: inline-size;
  display: flex;
  align-items: end;
  overflow: hidden;
  color: #f7f6f1;
  background: #182527;
}

.tb-live-hero,
.tb-live-hero * {
  box-sizing: border-box;
}

.tb-live-hero__media,
.tb-live-hero__scrim {
  position: absolute;
  inset: 0;
}

.tb-live-hero__media {
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.tb-live-hero__media > img,
.tb-live-hero__media > video,
.tb-live-hero__media > picture,
.tb-live-hero__media > picture > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tb-live-hero__scrim {
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgb(7 15 16 / 0.9) 0 32%, rgb(7 15 16 / 0.12) 72%),
    linear-gradient(0deg, rgb(7 15 16 / 0.55), transparent 56%);
}

.tb-live-hero__placeholder {
  width: 100%;
  height: 100%;
  background: #315b58;
}

.tb-live-hero__copy {
  position: relative;
  z-index: 2;
  display: flex;
  width: min(100%, 48rem);
  min-height: 36rem;
  min-height: clamp(36rem, 70cqi, 52rem);
  flex-direction: column;
  justify-content: end;
  padding: clamp(2rem, 5vw, 5.5rem);
  padding: clamp(2rem, 6cqi, 5.5rem);
}

.tb-live-hero__title {
  max-width: 44rem;
  margin: 0;
  font-size: clamp(3rem, 7vw, 7rem);
  font-size: clamp(3rem, 8.5cqi, 7rem);
  font-weight: 600;
  line-height: 0.96;
  letter-spacing: -0.035em;
  overflow-wrap: anywhere;
}

.tb-live-hero__copy p {
  max-width: 31rem;
  margin: 1.4rem 0 0;
  font-size: clamp(1rem, 1.8cqi, 1.22rem);
  line-height: 1.55;
}

.tb-live-hero__copy a {
  display: inline-flex;
  min-height: 3rem;
  align-items: center;
  justify-content: center;
  margin-top: 1.75rem;
  padding: 0.45rem 1.15rem;
  color: #151816;
  background: var(--tb-leh-accent);
  border-radius: 0.2rem;
  font-weight: 700;
  text-align: center;
  text-decoration: none;
  transition: background-color 150ms ease-out, transform 100ms ease-out;
}

.tb-live-hero__copy a:hover {
  background: #ffe38a;
}

.tb-live-hero__copy a:active {
  transform: translateY(1px);
}

.tb-live-hero__copy a:focus-visible {
  outline: 3px solid #f7f6f1;
  outline-offset: 4px;
}

@container (min-width: 28rem) {
  .tb-live-hero__copy a {
    white-space: nowrap;
  }
}

@container (max-width: 44rem) {
  .tb-live-hero__scrim {
    background: linear-gradient(0deg, rgb(7 15 16 / 0.92) 0 42%, rgb(7 15 16 / 0.12) 80%);
  }

  .tb-live-hero__copy {
    padding: 2rem 1.25rem 2.5rem;
  }
}

@media (max-width: 720px) {
  .tb-live-hero__scrim {
    background: linear-gradient(0deg, rgb(7 15 16 / 0.92) 0 42%, rgb(7 15 16 / 0.12) 80%);
  }

  .tb-live-hero__copy {
    padding: 2rem 1.25rem 2.5rem;
  }
}

@media (forced-colors: active) {
  .tb-live-hero__copy a {
    border: 2px solid ButtonText;
  }
}
